), dedup as (
  select distinct on (doc_number, check_in)
    source_row, id, ha, name, nationality, nationality_code, birth_date, birth_place, doc_number, doc_type, issuer_country, issuer_country_code, residence_country, residence_country_code, residence_city, check_in, check_out, sent_status, sent_at, send_error, send_batch_number, created_at, updated_at
  from source
  order by doc_number, check_in, source_row desc
)
insert into public.guest_records (
  id,
  ha,
  name,
  nationality,
  nationality_code,
  birth_date,
  birth_place,
  doc_number,
  doc_type,
  issuer_country,
  issuer_country_code,
  residence_country,
  residence_country_code,
  residence_city,
  check_in,
  check_out,
  sent_status,
  sent_at::timestamptz as sent_at,
  send_error,
  send_batch_number,
  created_at,
  updated_at
)
select
  id,
  ha,
  name,
  nationality,
  nationality_code,
  birth_date,
  birth_place,
  doc_number,
  doc_type,
  issuer_country,
  issuer_country_code,
  residence_country,
  residence_country_code,
  residence_city,
  check_in,
  check_out,
  sent_status,
  sent_at,
  send_error,
  send_batch_number,
  created_at,
  updated_at
from dedup
on conflict (doc_number, check_in) do update set
  ha = excluded.ha,
  name = excluded.name,
  nationality = excluded.nationality,
  nationality_code = excluded.nationality_code,
  birth_date = excluded.birth_date,
  birth_place = excluded.birth_place,
  doc_type = excluded.doc_type,
  issuer_country = excluded.issuer_country,
  issuer_country_code = excluded.issuer_country_code,
  residence_country = excluded.residence_country,
  residence_country_code = excluded.residence_country_code,
  residence_city = excluded.residence_city,
  check_out = excluded.check_out,
  sent_status = excluded.sent_status,
  sent_at = excluded.sent_at,
  send_error = excluded.send_error,
  send_batch_number = excluded.send_batch_number,
  updated_at = excluded.updated_at;
